const incoming = msg.payload;

// Ensure payload is a valid object
if (!incoming || typeof incoming !== 'object') {
    return null;
}

// Parse incoming metrics safely from ESP32
const voltage = +(incoming.voltage || 0).toFixed(2);
const current = +(incoming.current || 0).toFixed(2);
const power = +(incoming.power || (voltage * current)).toFixed(2);
const temp = +(incoming.temp || 0).toFixed(1);
const light = Math.floor(incoming.light || 0);
const status = incoming.status || "Healthy";
const alert = incoming.alert || "NO FAULT DETECTED";

let color = "#00E676";
if (status.includes("Dust")) color = "#FFB300";
else if (status.includes("Shade")) color = "#FFF176";
else if (status.includes("Temp") || status.includes("Overheating")) color = "#FF5252";
else if (status.includes("Fault")) color = "#FF1744";

const confidence = incoming.confidence || 99;
const timeStr = new Date().toLocaleTimeString();

// Power generation is derived from actual voltage unless explicitly provided
const genStatus = incoming.gen || (voltage > 0.2 ? "Active" : "Inactive");

const state = {
    row1: { voltage, current, power, temp, light },
    row2: { status, color, confidence, alert, gen: genStatus },
    row3: {
        panelHealth: status === "Healthy" ? "Normal" : status,
        battery: incoming.battery || "Connected",
        gen: genStatus
    },
    row4: { voltage, current, power, temp, light },
    row5: {
        esp: "ONLINE",
        wifi: "CONNECTED",
        mqtt: "LIVE STREAM ACTIVE",
        time: timeStr
    },
    row6: alert
};

flow.set('systemState', state);
return { payload: state };

const selectedRow = flow.get('selectedRow') || "row2";
const state = flow.get('systemState');
if (!state) return null;

let content = "";

switch (selectedRow) {
    case "row1":
        content = `<h3>Live Parameters</h3>
            <div>Voltage: ${state.row1.voltage} V</div>
            <div>Current: ${state.row1.current} A</div>
            <div>Power: ${state.row1.power} W</div>
            <div>Temperature: ${state.row1.temp} \u00b0C</div>
            <div>Light Intensity: ${state.row1.light} Lux</div>`;
        break;
    case "row2":
        content = `<h3>AI Health Prediction</h3>
            <span style="background-color:${state.row2.color}"></span>
            <span>${state.row2.status}</span>
            <div>Confidence: ${state.row2.confidence}%</div>
            <div>Power Generation: ${state.row2.gen}</div>`;
        break;
    case "row5":
        content = `<h3>System Status</h3>
            <div>ESP32: ${state.row5.esp}</div>
            <div>WiFi: ${state.row5.wifi}</div>
            <div>MQTT: ${state.row5.mqtt}</div>
            <div>Last Update: ${state.row5.time}</div>`;
        break;
}

// Live chart now updates on every message, regardless of which view is selected
const chartMsgs = [
    { payload: state.row1.voltage, topic: "Voltage (V)" },
    { payload: state.row1.current, topic: "Current (A)" },
    { payload: state.row1.power, topic: "Power (W)" },
    { payload: state.row1.temp, topic: "Temperature (\u00b0C)" },
    { payload: state.row1.light, topic: "Light (Lux)" }
];

return [{ payload: content }, chartMsgs];
